const listEvaluationRuns = `-- name: ListEvaluationRuns :many
SELECT run.id, run.supplier_id, run.relation_id, run.site_id, run.model, run.upstream_model, run.target_kind, run.purpose, run.status, run.suite_version, run.algorithm_version, run.random_seed, run.reference_id, run.planned_samples, run.completed_samples, run.requested_by, run.request_reason, run.error_code, run.error_message, run.requested_at, run.started_at, run.completed_at, run.next_retry_at, run.request_key, run.request_hash, supplier.name AS supplier_name, COUNT(*) OVER()::bigint AS total_count
FROM evaluation_runs run
JOIN suppliers supplier ON supplier.id = run.supplier_id
WHERE (
    $1::uuid IS NULL
    OR run.site_id = $1::uuid
    OR (
        run.site_id IS NULL
        AND EXISTS (
            SELECT 1 FROM site_suppliers relation
            WHERE relation.site_id = $1::uuid
              AND relation.supplier_id = run.supplier_id
        )
    )
)
  AND ($2::uuid IS NULL OR run.supplier_id = $2::uuid)
  AND ($3::text IS NULL OR run.model = $3::text)
  AND ($4::text IS NULL OR run.purpose = $4::text)
ORDER BY run.requested_at DESC, run.id DESC
LIMIT $6 OFFSET $5
`

